import{_ as r,c as i,o as l,a2 as o}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"自定义","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/customize.md","filePath":"zh-CN/guide/customize.md","lastUpdated":1793163976000}'),a={name:"zh-CN/guide/customize.md"};function n(e,t,s,d,g,h){return l(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="自定义" tabindex="-1">自定义 <a class="header-anchor" href="#自定义" aria-label="Permalink to &quot;自定义&quot;">​</a></h1><p>通过自定义你的归档管理体验，让 NueZip 真正属于你。本指南涵盖所有你可以个性化的内容。</p><h2 id="通用偏好" tabindex="-1">通用偏好 <a class="header-anchor" href="#通用偏好" aria-label="Permalink to &quot;通用偏好&quot;">​</a></h2><p>打开 <strong>NueZip → 设置</strong>（或按下 <code>Cmd+,</code>）以访问所有自定义选项。</p><h3 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h3><ul><li><strong>主题</strong>：在浅色、深色或跟随系统（跟随 macOS 外观）之间选择</li><li><strong>图标样式</strong>：设置为单色或彩色菜单栏图标</li><li><strong>语言</strong>：从支持的语言中选择（英语、中文、日本語、한국어 等）</li></ul><h2 id="压缩默认值" tabindex="-1">压缩默认值 <a class="header-anchor" href="#压缩默认值" aria-label="Permalink to &quot;压缩默认值&quot;">​</a></h2><p>设置你偏好的压缩默认值：</p><table tabindex="0"><thead><tr><th>设置</th><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>默认格式</strong></td><td>ZIP、7z、TAR、GZIP、BZIP2、XZ</td><td>用于快速压缩的归档格式</td></tr><tr><td><strong>压缩级别</strong></td><td>存储、快速、普通、最大、极限</td><td>速度与压缩比之间的权衡</td></tr><tr><td><strong>加密</strong></td><td>无、AES-128、AES-256</td><td>ZIP/7z 归档的默认加密</td></tr><tr><td><strong>卷大小</strong></td><td>自定义（MB）</td><td>多卷归档的默认拆分大小</td></tr></tbody></table><h3 id="示例配置" tabindex="-1">示例配置 <a class="header-anchor" href="#示例配置" aria-label="Permalink to &quot;示例配置&quot;">​</a></h3><p>日常使用：</p><ul><li><strong>格式</strong>：ZIP</li><li><strong>级别</strong>：普通</li><li><strong>加密</strong>：AES-256（用于敏感文件）</li><li><strong>分卷</strong>：关闭</li></ul><p>归档用途：</p><ul><li><strong>格式</strong>：7-Zip</li><li><strong>级别</strong>：极限</li><li><strong>加密</strong>：AES-256</li><li><strong>分卷</strong>：4.7 GB（以适配 DVD）</li></ul><h2 id="解压偏好" tabindex="-1">解压偏好 <a class="header-anchor" href="#解压偏好" aria-label="Permalink to &quot;解压偏好&quot;">​</a></h2><p>自定义解压行为：</p><ul><li><strong>默认解压到子文件夹</strong>：解压时自动创建带名称的文件夹</li><li><strong>解压后打开文件夹</strong>：在 Finder 中显示解压出的内容</li><li><strong>覆盖行为</strong>：询问、总是覆盖或跳过已有文件</li><li><strong>保留文件日期</strong>：保留归档中的原始时间戳</li></ul><h2 id="finder-扩展" tabindex="-1">Finder 扩展 <a class="header-anchor" href="#finder-扩展" aria-label="Permalink to &quot;Finder 扩展&quot;">​</a></h2><p>管理 Finder 上下文菜单集成：</p><ul><li><strong>启用/禁用</strong>：开启或关闭右键菜单项</li><li><strong>快速操作</strong>：选择哪些操作出现在上下文菜单中 <ul><li>解压到此</li><li>解压到文件夹</li><li>压缩为 ZIP</li><li>带选项压缩</li></ul></li></ul><p>在以下位置管理：<strong>系统设置 → 隐私与安全性 → 扩展 → Finder 扩展</strong></p><h2 id="菜单栏-托盘-图标" tabindex="-1">菜单栏（托盘）图标 <a class="header-anchor" href="#菜单栏-托盘-图标" aria-label="Permalink to &quot;菜单栏（托盘）图标&quot;">​</a></h2><p>自定义菜单栏放置面板：</p><ul><li><strong>在菜单栏中显示</strong>：启用/禁用托盘图标</li><li><strong>自动关闭面板</strong>：解压后关闭放置面板</li><li><strong>最近归档</strong>：显示的最近项目数量</li><li><strong>关闭时退出</strong>：应用是否在后台保持运行</li></ul><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><ul><li><strong>显示完成提醒</strong>：长时间操作完成时通知</li><li><strong>显示错误提醒</strong>：操作失败时显示通知</li><li><strong>声音</strong>：操作完成时播放声音</li></ul><h2 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h2><p>在 <strong>设置 → 通用</strong> 中访问这些设置：</p><ul><li><strong>语言</strong>：在英语、中文、日本語 等之间切换</li><li><strong>登录时启动</strong>：登录时 NueZip 自动启动</li><li><strong>主题</strong>：浅色或深色模式（默认跟随系统）</li><li><strong>菜单栏图标</strong>：显示或隐藏菜单栏图标</li></ul><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li>一次性设置你喜欢的压缩默认值，以加快日常归档速度</li><li>启用 &quot;登录时启动&quot;，让 NueZip 始终一键可达</li><li>使用 Finder 扩展获得最快的解压/压缩工作流</li><li>定期在系统设置中检查文件夹访问权限，保持整洁</li></ul>',31)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
